class Solution {
    public int mostFrequentPrime(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int N = 1000000;
        boolean[] sieve = new boolean[N];
        java.util.Arrays.fill(sieve, true);
        sieve[0] = sieve[1] = false;
        for (int i = 2; (long) i * i < N; i++)
            if (sieve[i])
                for (long j = (long) i * i; j < N; j += i) sieve[(int) j] = false;
        int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1}, dy = {-1, 0, 1, -1, 1, -1, 0, 1};
        java.util.Map<Integer, Integer> cnt = new java.util.HashMap<>();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                for (int d = 0; d < 8; d++) {
                    int x = i + dx[d], y = j + dy[d], v = mat[i][j];
                    while (x >= 0 && x < m && y >= 0 && y < n) {
                        v = v * 10 + mat[x][y];
                        if (v > 10 && sieve[v]) cnt.merge(v, 1, Integer::sum);
                        x += dx[d]; y += dy[d];
                    }
                }
        int best = -1, bf = 0;
        for (var e : cnt.entrySet()) {
            int v = e.getKey(), f = e.getValue();
            if (f > bf || (f == bf && v > best)) { best = v; bf = f; }
        }
        return best;
    }
}

